/**
 * The agent Sessions the TTOken Code issues board started, remembered in browser storage by repository and issue,
 * so the board can show an issue under "Agent working" and open its Session again.
 * Generated by ttoken/apply-brand.mjs from ttoken/forge/client/agents.ts; edit it there.
 */

/** Session ids by issue number, by repository key `host/owner/name`; the values are plain strings from storage. */
export type AgentSessions = Readonly<Record<string, Readonly<Record<string, string>>>>

/**
 * The remembered Sessions of one repository. Browser storage can hold anything, so a value in another form reads as
 * no Session.
 * @param all - every remembered Session as storage returned it.
 * @param repository - repository key `host/owner/name`.
 * @returns Session ids by issue number.
 */
export function agentsOf(all: unknown, repository: string): Readonly<Record<string, string>> {
  if (typeof all !== 'object' || all === null) return {}
  const issues = (all as Record<string, unknown>)[repository]
  if (typeof issues !== 'object' || issues === null) return {}
  return Object.fromEntries(Object.entries(issues as Record<string, unknown>)
    .filter((entry): entry is [string, string] => typeof entry[1] === 'string'))
}

/**
 * Remember the Session started for an issue. A Session's draft is replaced when the board starts it for another
 * issue, so every other issue that named the same Session forgets it.
 * @param all - every remembered Session as storage returned it.
 * @param repository - repository key `host/owner/name`.
 * @param issue - issue number.
 * @param sessionId - the started Session.
 * @returns the next remembered Sessions.
 */
export function withAgent(all: unknown, repository: string, issue: number, sessionId: string): AgentSessions {
  const kept = Object.entries(agentsOf(all, repository)).filter(([, id]) => id !== sessionId)
  return { ...validOf(all), [repository]: { ...Object.fromEntries(kept), [String(issue)]: sessionId } }
}

/**
 * Forget the Session remembered for an issue.
 * @param all - every remembered Session as storage returned it.
 * @param repository - repository key `host/owner/name`.
 * @param issue - issue number.
 * @returns the next remembered Sessions.
 */
export function withoutAgent(all: unknown, repository: string, issue: number): AgentSessions {
  const kept = Object.entries(agentsOf(all, repository)).filter(([number]) => number !== String(issue))
  return { ...validOf(all), [repository]: Object.fromEntries(kept) }
}

/** Every repository's remembered Sessions in the stored form, dropping values in another form. */
function validOf(all: unknown): AgentSessions {
  if (typeof all !== 'object' || all === null) return {}
  return Object.fromEntries(Object.keys(all).map(repository => [repository, agentsOf(all, repository)]))
}
